solution:
function resume(e: { nom: string; classe?: string; notes?: number[] }): string {
  const classe = e.classe ?? "classe inconnue";
  const notes = e.notes ?? [];
  if (notes.length === 0) return `${e.nom} (${classe}) : pas de note`;
  const m = Math.round(notes.reduce((s, n) => s + n, 0) / notes.length * 10) / 10;
  return `${e.nom} (${classe}) : moyenne ${m}`;
}
